var body=root.querySelector('.trx3-hex-body'),at=root.querySelector('.trx3-hex-at'),msg=root.querySelector('.trx3-hex-msg');
var HX='0123456789abcdef',ROWS=7,base=0xa0,data=[],tid=0,cur=0,t=0;
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function hx(v,w){var s=v.toString(16);while(s.length<w){s='0'+s;}return s;}
function ch(v){return v>=32&&v<127?String.fromCharCode(v):'.';}
function esc(c){return c==='<'?'&lt;':(c==='&'?'&amp;':c);}
var SEED=[0x4d,0x5a,0x90,0x00,0x03,0x00,0x00,0x00,0x04,0x00,0x00,0x00,0xff,0xff,0x00,0x00,0xb8,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x40,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0xde,0xad,0xbe,0xef,0x0e,0x1f,0xba,0x0e,0x00,0xb4,0x09,0xcd,0x21,0xb8,0x01,0x4c,0x54,0x68,0x69,0x73,0x20,0x70,0x72,0x6f];
var i;for(i=0;i<ROWS*8;i++){data.push(SEED[i%SEED.length]);}
function render(flick){
  var h='',r,c,v,off;
  for(r=0;r<ROWS;r++){
    off=base+r*8;
    var hexs='',asc='';
    for(c=0;c<8;c++){
      v=data[r*8+c];
      var hit=(r===4&&c>=0&&c<4);
      var fl=flick&&flick[0]===r&&flick[1]===c;
      var cls=hit?'trx3-hex-hit':(fl?'trx3-hex-fl':'');
      hexs+=(c?' ':'')+(cls?'<span class="'+cls+'">'+hx(v,2)+'</span>':hx(v,2));
      asc+=esc(ch(v));
    }
    h+='<div class="trx3-hex-row'+(r===cur?' trx3-hex-cur':'')+'"><span class="trx3-hex-off">'+hx(off,6)+'</span><span class="trx3-hex-bs">'+hexs+'</span><span class="trx3-hex-g">│</span><span class="trx3-hex-as">'+asc+'</span></div>';
