}
function tick(){
  t++;
  var r=Math.floor(Math.random()*ROWS),c=Math.floor(Math.random()*8);
  if(!(r===4&&c<4)){data[r*8+c]=Math.floor(Math.random()*256);}
  if(t%9===0){cur=(cur+1)%ROWS;at.textContent='0x'+hx(base+cur*8,4);}
  if(t%9===4&&cur===4){root.className='trx3-hex trx3-hex-found';msg.textContent='DEADBEEF @ 0x00c0';}
  else if(t%9===0&&cur===0){root.className='trx3-hex';msg.textContent='scanning…';}
  render([r,c]);
  tid=setTimeout(tick,110);
}
render(null);
if(reduce){cur=4;root.className='trx3-hex trx3-hex-found';msg.textContent='DEADBEEF @ 0x00c0';at.textContent='0x00c0';render(null);}
else{tid=setTimeout(tick,160);}

