var cells=root.querySelectorAll('.trx3-bf-cell'),grid=root.querySelector('.trx3-bf-grid'),lk=root.querySelector('.trx3-bf-lk'),tried=root.querySelector('.trx3-bf-tried'),hz=root.querySelector('.trx3-bf-hz');
var CH='abcdefghijklmnopqrstuvwxyz0123456789',KEY='r00tk1',lock=0,n=0,t=0,tid=0;
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function rnd(){return CH.charAt(Math.floor(Math.random()*CH.length));}
function noise(){
  var rows=3,cols=42,s='',r,c;
  for(r=0;r<rows;r++){
    for(c=0;c<cols;c++){s+=Math.random()<0.06?'<span class="trx3-bf-lit">'+rnd()+'</span>':rnd();}
    if(r<rows-1){s+='\n';}
  }
  grid.innerHTML=s;
}
function paint(){
  var i;
  for(i=0;i<cells.length;i++){
    if(i<lock){cells[i].className='trx3-bf-cell trx3-bf-on';cells[i].textContent=KEY.charAt(i);}
    else{cells[i].className='trx3-bf-cell';cells[i].textContent=rnd();}
  }
  lk.textContent=lock+'/6';
  tried.textContent=String(n).replace(/\B(?=(\d{3})+(?!\d))/g,',');
}
function tick(){
  t++;
  n+=6000+Math.floor(Math.random()*9000);
  if(t%3===0){hz.textContent=(780+Math.floor(Math.random()*90))+'k/s';}
  if(t%9===0&&lock<6){lock++;}
  if(lock>=6&&t%9===0){tid=setTimeout(function(){lock=0;n=0;t=0;paint();noise();tid=setTimeout(tick,300);},1800);paint();noise();return;}
  paint();if(t%2===0){noise();}
  tid=setTimeout(tick,95);
}
noise();paint();
if(reduce){lock=4;n=4182993;hz.textContent='812k/s';paint();}
else{tid=setTimeout(tick,160);}

