var log=root.querySelector('.trx3-stamp-log'),word=root.querySelector('.trx3-stamp-word');
var LINES=['> exploit cve-2026-1181 … ok','> payload staged 4.2kb','> handshake accepted'];
var GL='#@%&$*/|<>=+ABCDEF0123456789';
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var tid=0,sid=0,i=0;
function scramble(){
  var s='',k;for(k=0;k<14;k++){s+=GL.charAt(Math.floor(Math.random()*GL.length));}
  word.textContent=s;
}
function typeLine(txt,k,done){
  if(k>txt.length){log.appendChild(document.createElement('br'));done();return;}
  var last=log.lastChild;
  if(last&&last.nodeType===3){last.nodeValue=txt.slice(0,k);}else{log.appendChild(document.createTextNode(txt.slice(0,k)));}
  tid=setTimeout(function(){typeLine(txt,k+1,done);},18);
}
function run(){
  root.className='trx3-stamp';log.textContent='';i=0;
  sid=setInterval(scramble,70);
  next();
}
function next(){
  if(i>=LINES.length){
    clearInterval(sid);
    word.textContent='ACCESS GRANTED';
    root.className='trx3-stamp trx3-stamp-go';
    tid=setTimeout(run,4200);
    return;
  }
  typeLine(LINES[i++],1,function(){tid=setTimeout(next,180);});
}
if(reduce){log.textContent=LINES.join('\n');word.textContent='ACCESS GRANTED';root.className='trx3-stamp trx3-stamp-go';}
else{run();}
